            height: 18px;
            font-size: 11px;
            display: flex;
            align-items: center;
            justify-content: center;
            cursor: pointer;
            z-index: 10;
        }

        .ai-input-row {
            display: flex;
            align-items: flex-end;
            gap: 10px;
        }

        #aiInput {
            flex-grow: 1;
            background: transparent;
            border: none;
            color: #dfe1e5;
            font-size: 15px;
            line-height: 1.6;
            padding: 5px 0;
            outline: none;
            resize: none;
