        #aiInput::placeholder { color: #6e7073; }

        .ai-input-footer {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding-top: 5px;
        }

        .ai-footer-icons {
            display: flex;
            gap: 16px;
            color: #afb1b3;
            font-size: 20px;
            align-items: center;
        }

        .ai-footer-icons span { cursor: pointer; transition: color 0.2s; display: flex; align-items: center; }
        .ai-footer-icons span:hover { color: #fff; }

        .ai-send-btn-new {
            background: transparent;
            border: none;
            color: #4e5157;
            cursor: pointer;
            padding: 8px;
            display: flex;
