            const generationConfig = {
                temperature: 0, // سلوك حتمي ودقيق
                topP: 0.1,
                maxOutputTokens: 2048
            };

            async function runToolLoop(history, activeModel = null, retryModels = []) {
                // 🛑 فحص إذا طلب المستخدم الإيقاف يدوياً
                if (stopAiRequested) {
                    stopAiRequested = false;
                    localStorage.removeItem('gemini_pending_history');
                    return { text: "🛑 تم إيقاف العملية يدوياً بناءً على طلبك.", model: "System" };
                }

                // 💾 حفظ حالة المحادثة الحالية للاسترداد
                localStorage.setItem('gemini_pending_history', JSON.stringify(history));
                startAiTimer(); // ⏱️ بدء عداد الانتظار

                // 🔄 بروتوكول الاستمرارية العميقة (Deep Persistence Protocol)
                if (retryModels.length >= modelNames.length) {
                    const retryCount = (parseInt(localStorage.getItem('gemini_retry_count') || "0")) + 1;
                    localStorage.setItem('gemini_retry_count', retryCount);

                    if (retryCount > 100) { // التوقف فقط بعد 100 محاولة كبرى (حوالي ساعة من الانتظار) لضمان الاستمرارية القصوى
                        localStorage.removeItem('gemini_retry_count');
                        localStorage.removeItem('gemini_pending_history');
                        return { text: "❌ تم الوصول للحد الأقصى من المحاولات (100). يرجى التحقق من اتصالك بالإنترنت أو مفتاح الـ API.", model: "System Error" };
                    }

                    console.log(`🔄 محاولة استمرارية رقم ${retryCount}. جميع النماذج تحت الضغط.`);
                    addMessageToUi('ai', `⏳ جميع النماذج مشغولة أو بلغت حد الاستخدام (محاولة ${retryCount}). سأنتظر 30 ثانية ثم أستأنف العمل تلقائياً... لن يتم إيقاف العملية.`, 'System');
                    await new Promise(r => setTimeout(r, 30000));
                    return await runToolLoop(history, null, []);
                }
                localStorage.setItem('gemini_retry_count', "0"); // تصغير العداد عند وجود نموذج متاح

                // استخدام قائمة الموديلات المتاحة مع استثناء الموديلات التي فشلت سابقاً في هذه الدورة
                const modelsToTry = activeModel ? [activeModel, ...modelNames.filter(m => m !== activeModel && !retryModels.includes(m))] : modelNames;

                for (const modelName of modelsToTry) {
                    // تحديث رسالة التفكير لتعكس النموذج الحالي
                    const thinkMsg = document.querySelector('.msg.ai:last-child');
                    if (thinkMsg && thinkMsg.innerText.includes("جاري التفكير")) {
                        thinkMsg.innerText = `🧠 جاري التفكير باستخدام ${modelName}...`;
                    }

                    // تحديث منطق الإصدار لضمان التوافق التام مع نماذج 2026
                    const apiVersion = (modelName.includes('exp') || modelName.includes('preview')) ? 'v1beta' : 'v1';
                    const url = `https://generativelanguage.googleapis.com/${apiVersion}/models/${modelName}:generateContent?key=${key}`;

                    try {
                        // 🛰️ نظام حارس الوقت (Watchdog) - 60 ثانية كحد أقصى للرد
                        const controller = new AbortController();
                        const timeoutId = setTimeout(() => controller.abort(), 60000);

                        const res = await fetch(url, {
                            method: 'POST',
                            headers: { 'Content-Type': 'application/json' },
                            signal: controller.signal,
                            body: JSON.stringify({
                                system_instruction: systemInstruction,
                                contents: history.map(h => ({ role: h.role, parts: h.parts })),
                                tools: tools,
                                generationConfig: generationConfig
                            })
                        });
                        clearTimeout(timeoutId);

                        const data = await res.json();

                        if (!res.ok) {
                            lastError = data.error?.message || "Unknown Error";
                            console.error(`🔴 Gemini API Error (${modelName}):`, data);
                            // ⏳ التعامل الذكي مع حد الاستخدام (Rate Limit 429)
                            if (res.status === 429) {
                                console.warn(`⏳ حد الاستخدام مع ${modelName}. بدء مؤقت الانتظار الذكي...`);
                                addMessageToUi('ai', `⏳ تم بلوغ حد الاستخدام لـ ${modelName}. سأنتظر 15 ثانية ثم أحاول التبديل أو الإكمال تلقائياً...`, 'System');
                                await new Promise(r => setTimeout(r, 15000));
                                retryModels.push(modelName);
                                continue;
                            }

                            const isDeprecated = lastError.includes("no longer available") || lastError.includes("not found");
                            if (res.status === 404 || res.status === 503 || isDeprecated) {
                                retryModels.push(modelName);
                                continue;
                            }
                            return { text: `❌ خطأ من جوجل (${res.status}): ${lastError}`, model: modelName };
                        }

                        const parts = data.candidates?.[0]?.content?.parts || [];
                        const part = parts.find(p => p.functionCall);
                        const textPart = parts.find(p => p.text);
                        const thought = textPart ? textPart.text : null;

