                                    toolResult = `📊 ملخص محرك VSA التقني:\n` +
                                                 `- عدد دروس VSA: ${vsaStats.lessons}\n` +
                                                 `- إجمالي الفيديوهات التعليمية: ${vsaStats.videos}\n` +
