                            else if (name === "requestIdeTask") {
                                try {
                                    const bridgeFile = 'ide_bridge.json';
                                    const payload = {
                                        id: Date.now(),
                                        timestamp: new Date().toLocaleString('ar-EG'),
                                        task: args.task_description,
                                        status: "pending_ide_action",
                                        requested_by: "Web_Mastermind"
                                    };
                                    toolResult = await writeFile(bridgeFile, JSON.stringify(payload, null, 2), `🚀 جسر التواصل: طلب مهمة جديدة من IDE [${args.task_description.substring(0, 20)}...]`);
                                } catch(e) { toolResult = `❌ فشل إرسال الطلب للجسر: ${e.message}`; }
                            }
                            else if (name === "getSiteContext") toolResult = "سياق الموقع: أكاديمية VSA متخصصة في التداول والتحليل الفني والزمني.";
                            else if (name === "injectGlobalStyles") {
                                const style = document.createElement('style');
                                style.textContent = args.css_code;
                                document.head.appendChild(style);
                                toolResult = "✅ تم تطبيق التنسيق الجديد بنجاح.";
                            }

                            updateToolStepStatus(stepId, !String(toolResult).includes('❌') && !String(toolResult).includes('خطأ'), toolResult);

                            history.push({ role: "model", parts: parts });
                            history.push({ role: "user", parts: [{ functionResponse: { name: name, response: { content: toolResult } } }] });

                            logToTerminal(`Tool Result Received (${name})`, 'info');
                            if (toolResult.includes('❌') || toolResult.includes('خطأ')) logToTerminal(toolResult, 'error');
                            else logToTerminal("Action completed successfully.", 'info');

                            // العودة للموديل بالنتيجة (مع إمكانية التبديل إذا فشل الموديل الحالي في الخطوة القادمة)
                            return await runToolLoop(history, modelName, retryModels);
                        }

                        const finalTurn = { role: "model", parts: parts, model: modelName };
                        chatHistory = history.concat([finalTurn]);
                        if (chatHistory.length > 50) chatHistory = chatHistory.slice(-50);
                        saveChatToStorage();
                        localStorage.removeItem('gemini_pending_history'); // مسح حالة الانتظار عند النجاح
                        stopAiTimer(); // ⏱️ إيقاف العداد
                        return { text: thought || "تمت العملية بنجاح.", model: modelName };
                    } catch (err) {
                        console.error(`Error with ${modelName}:`, err);
                        retryModels.push(modelName);
                        continue;
                    }
                }

                // إذا فشلت كل المحاولات بعد الانتظار الطويل
                return { text: `❌ فشلت جميع المحاولات. آخر خطأ تم رصده: ${lastError}`, model: "System Error" };
            }

            // تشغيل الحلقة مع السياق الحالي
            return await runToolLoop([...chatHistory, currentTurn]);
        }

